window.ScripturaLexicons.BDAG_PART_0243 = {"source":"BDAG","searchAnchorId":"bdag-search-anchor","entryAnchorId":"bdag-entry-anchor","rowsHtml":"<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0243-01\" data-source=\"BDAG\" data-search=\"Ναχώρ, ὁ nome próprio masculino Naor BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Ναχώρ, ὁ</td><td>nome próprio masculino</td><td>Naor</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0243-02\" data-source=\"BDAG\" data-search=\"νεανίας, ου, ὁ substantivo masculino jovem; rapaz BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">νεανίας, ου, ὁ</td><td>substantivo masculino</td><td>jovem; rapaz</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0243-03\" data-source=\"BDAG\" data-search=\"νεᾶνις, ιδος, ἡ substantivo feminino jovem mulher; moça BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">νεᾶνις, ιδος, ἡ</td><td>substantivo feminino</td><td>jovem mulher; moça</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0243-04\" data-source=\"BDAG\" data-search=\"νεανίσκος, ου, ὁ substantivo masculino jovem; servo BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">νεανίσκος, ου, ὁ</td><td>substantivo masculino</td><td>jovem; servo</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0243-05\" data-source=\"BDAG\" data-search=\"Νεάπολις remissão ver νέος 5 BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Νεάπολις</td><td>remissão</td><td>ver νέος 5</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0243-06\" data-source=\"BDAG\" data-search=\"Νεεμάν remissão ver Ναιμάν BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Νεεμάν</td><td>remissão</td><td>ver Ναιμάν</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0243-07\" data-source=\"BDAG\" data-search=\"νεῖκος, εος, τό substantivo neutro; variante textual forma itacística de νῖκος BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">νεῖκος, εος, τό</td><td>substantivo neutro; variante textual</td><td>forma itacística de νῖκος</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0243-08\" data-source=\"BDAG\" data-search=\"νεκρός, ά, όν adjetivo e substantivo masculino morto; cadáver; pessoa espiritualmente morta BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">νεκρός, ά, όν</td><td>adjetivo e substantivo masculino</td><td>morto; cadáver; pessoa espiritualmente morta</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0243-09\" data-source=\"BDAG\" data-search=\"νεκροφόρος, ον adjetivo e substantivo masculino transportador de cadáver; portador de morte BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">νεκροφόρος, ον</td><td>adjetivo e substantivo masculino</td><td>transportador de cadáver; portador de morte</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0243-10\" data-source=\"BDAG\" data-search=\"νεκρόω verbo mortificar; fazer cessar; tornar impotente BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">νεκρόω</td><td>verbo</td><td>mortificar; fazer cessar; tornar impotente</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0243-11\" data-source=\"BDAG\" data-search=\"νέκρωσις, εως, ἡ substantivo feminino morte; mortificação; estado de inatividade BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">νέκρωσις, εως, ἡ</td><td>substantivo feminino</td><td>morte; mortificação; estado de inatividade</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0243-12\" data-source=\"BDAG\" data-search=\"νέμω verbo pastar; alimentar-se BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">νέμω</td><td>verbo</td><td>pastar; alimentar-se</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0243-13\" data-source=\"BDAG\" data-search=\"νεομηνία, ας, ἡ substantivo feminino lua nova; primeiro dia do mês BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">νεομηνία, ας, ἡ</td><td>substantivo feminino</td><td>lua nova; primeiro dia do mês</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0243-14\" data-source=\"BDAG\" data-search=\"νέος, α, ον adjetivo e substantivo novo; jovem; noviço; Neápolis BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">νέος, α, ον</td><td>adjetivo e substantivo</td><td>novo; jovem; noviço; Neápolis</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0243-15\" data-source=\"BDAG\" data-search=\"νεοσσός remissão ver νοσσός BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">νεοσσός</td><td>remissão</td><td>ver νοσσός</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0243-16\" data-source=\"BDAG\" data-search=\"νεότης, τητος, ἡ substantivo feminino juventude BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">νεότης, τητος, ἡ</td><td>substantivo feminino</td><td>juventude</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0243-17\" data-source=\"BDAG\" data-search=\"νεόφυτος, ον adjetivo recém-plantado; recém-convertido BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">νεόφυτος, ον</td><td>adjetivo</td><td>recém-plantado; recém-convertido</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0243-18\" data-source=\"BDAG\" data-search=\"νέρτερος, α, ον adjetivo comparativo inferior; subterrâneo; mundo inferior BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">νέρτερος, α, ον</td><td>adjetivo comparativo</td><td>inferior; subterrâneo; mundo inferior</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0243-19\" data-source=\"BDAG\" data-search=\"Νέρων, ωνος, ὁ nome próprio masculino Nero BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Νέρων, ωνος, ὁ</td><td>nome próprio masculino</td><td>Nero</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0243-20\" data-source=\"BDAG\" data-search=\"Νευης nome próprio masculino; variante textual variante do nome do rico de Lucas BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Νευης</td><td>nome próprio masculino; variante textual</td><td>variante do nome do rico de Lucas</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n","cardsHtml":"<article class=\"entry-card\" id=\"entry-bdag-0243-01\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Ναχώρ, ὁ</h1><div class=\"entry-meta\"><span>nome próprio masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">Ναχώρ</span>, <span class=\"greek\">ὁ</span>, indeclinável (<span class=\"hebrew\" lang=\"he\" dir=\"rtl\">נָחוֹר</span>), Naor (Gen 11:22–26; 1 Ch 1:26f; Philo, Congr. Erud. Gr. 43.—Em Joseph. <span class=\"greek\">Ναχώρης</span>, <span class=\"greek\">ου</span> [Ant. 1, 153]), na genealogia de Jesus <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.3.34\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 3:34</a>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0243-02\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">νεανίας, ου, ὁ</h1><div class=\"entry-meta\"><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">νεανίας</span>, <span class=\"greek\">ου</span>, <span class=\"greek\">ὁ</span> (Trag., Hdt. e outros; inscrições; POxy 471, 114 [II a.d.]; LXX, TestSol; Jos., Bell. 2, 409, Vi. 129; 170; TestJos 12:3; 16:1), jovem, rapaz (dos cerca de 24 aos 40 anos; Diog. L. 8, 10; Philo, Cher. 114; Lob. sobre Phryn. p. 213.—FBoll, D. Lebens-alter: NJklA 31, 1913, 89ff) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.7.58\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 7:58</a>; 20:9; 23:17, 18 v.l., 22 v.l; Hv 1, 4, 1 (aqui também é provável o sentido figurado servo; cf. Judg 16:26 B).—VLeinieks, The City of Dionysos ’96, 199–209 (sobre o esquema da terceira e da quarta classes etárias no vocabulário grego). Schmidt, Syn. 22–35. DELG s.v. <span class=\"greek\">νέος</span> 3. M-M. Sv.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0243-03\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">νεᾶνις, ιδος, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">νεᾶνις</span>, <span class=\"greek\">ιδος</span>, <span class=\"greek\">ἡ</span> (Hom. e outros; LXX [com <span class=\"greek\">παρθένος</span> Dt 22:23–29], JosAs; Just., D. 84, 3), jovem mulher, moça (inclui mulheres na adolescência) GJs 9:2.).—AKamesar, The Virgin of Is 7:14, the Philological Argument from the Second to the Fifth Century: JTS 41, ’90, 51–75.—DELG s.v. <span class=\"greek\">νέος</span> 3.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0243-04\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">νεανίσκος, ου, ὁ</h1><div class=\"entry-meta\"><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">νεανίσκος</span>, <span class=\"greek\">ου</span>, <span class=\"greek\">ὁ</span> (Hdt. e outros; inscrições, papiros, LXX; Jos., Ant. 6, 179, Vi. 126; Test12Patr. No grego posterior, mais comum que <span class=\"greek\">νεανίας</span>), diminutivo de <span class=\"greek\">νεάν</span>.</p><p class=\"entry-text\">① Homem relativamente jovem, jovem, rapaz (sobre os limites cronológicos dessa fase da vida, cf. o que foi dito em <span class=\"greek\">νεανίας</span> e ver Philo, Op. M. 105; uma inscrição de Delos, BCH 13, 1889, 420ff, apresenta uma série de classes etárias: <span class=\"greek\">παῖδες</span>, <span class=\"greek\">ἔφηβοι</span>, <span class=\"greek\">νεανίσκοι</span> e equipara <span class=\"greek\">ν</span>. a <span class=\"greek\">νεός</span> [Forbes p. 61]) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.19.20\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 19:20</a>, 22; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.14.51\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 14:51</a> (SJohnson, The Identity and Significance of the Neaniskos in Mark: Forum 8, ’92, 123–39); 16:5 (cf. Jos., Ant. 5, 213; sobre a relação com 14:51 ver BvanIersel, CBQ 58, ’96, 261, n. 52 [bibliografia]); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.7.14\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 7:14</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.2.17\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 2:17</a> (Jo 3:1); 20:12 D; 23:18, 22; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1JN.2.13\" target=\"_blank\" rel=\"noopener noreferrer\">1J 2:13</a>f; Hv 2, 4, 1; 3, 1, 6ff; 3, 2, 5; 3, 4, 1; 3, 10, 1 e 7; Hs 6, 1, 5; 6, 2, 6; GPt 9:37; 13:55; AcPl Ha 3, 28; 4, 2 (referente a um ser celestial).</p><p class=\"entry-text\">② Jovem que exerce a função de servidor, servo (Lucian, Alex. 53; Gen 14:24, talvez já em PEdg 4 [=Sb 6710], 6 [259 b.c.]) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.14.51\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 14:51</a>b v.l. <span class=\"greek\">οἱ</span> <span class=\"greek\">νεανίσκοι</span>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.5.10\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 5:10</a> (embora aqui a referência possa ser simplesmente a jovens da congregação, que naturalmente prestariam esse serviço); AcPt Ox 849 recto, 19–20.—CForbes, NEOI: A Contribution to the Study of Greek Associations ’33, 61–63.—DELG s.v. <span class=\"greek\">νέος</span> 3. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0243-05\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Νεάπολις</h1><div class=\"entry-meta\"><span>remissão</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">Νεάπολις</span>: ver <span class=\"greek\">νέος</span> 5.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0243-06\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Νεεμάν</h1><div class=\"entry-meta\"><span>remissão</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">Νεεμάν</span>: ver <span class=\"greek\">Ναιμάν</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0243-07\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">νεῖκος, εος, τό</h1><div class=\"entry-meta\"><span>substantivo neutro; variante textual</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">νεῖκος</span>, <span class=\"greek\">εος</span>, <span class=\"greek\">τό</span>, como variante de leitura em <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.15.54\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 15:54</a>f, não é a palavra que significa «contenda», de grafia idêntica (Hom. e outros), mas uma forma itacística de <span class=\"greek\">νῖκος</span>; ver esse verbete.—DELG s.v. <span class=\"greek\">νίκη</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0243-08\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">νεκρός, ά, όν</h1><div class=\"entry-meta\"><span>adjetivo e substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">νεκρός</span>, <span class=\"greek\">ά</span>, <span class=\"greek\">όν</span></p><p class=\"entry-text\">A. Como adjetivo (talvez já em Hom., certamente em Pind.; em Ath., apenas no título R.).</p><p class=\"entry-text\">① Relativo ao estado de privação da vida, morto, a respeito de pessoas, literalmente: <span class=\"greek\">καταπίπτειν</span> <span class=\"greek\">νεκρόν</span> cair morto <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.28.6\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 28:6</a>. <span class=\"greek\">ἤρθη</span> <span class=\"greek\">νεκρός</span> foi levantado morto 20:9 (outra possibilidade é como morto, por morto: Lucian, Ver. Hist. 1, 22; Eunapius, Vi. Soph. 76 <span class=\"greek\">συγχωρήσατε</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">νεκρῷ</span> [aquele que está gravemente enfermo] <span class=\"greek\">με</span> <span class=\"greek\">δοῦναι</span> <span class=\"greek\">φάρμακον</span>.—<span class=\"greek\">ἤρθη</span> <span class=\"greek\">ν</span>. como em TestJud 9:3). <span class=\"greek\">νεκρὸς</span> <span class=\"greek\">κεῖται</span> (Mel., P. 90, 672), jaz morto, AcPt Ox 849 recto, 15.—<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.5.10\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 5:10</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.2.26\" target=\"_blank\" rel=\"noopener noreferrer\">Js 2:26</a>a. <span class=\"greek\">ἔπεσα</span> <span class=\"greek\">πρὸς</span> <span class=\"greek\">τοὺς</span> <span class=\"greek\">πόδας</span> <span class=\"greek\">αὐτοῦ</span> <span class=\"greek\">ὡς</span> <span class=\"greek\">ν</span>. caí a seus pés como se estivesse morto <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.1.17\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 1:17</a> (<span class=\"greek\">ὡς</span> <span class=\"greek\">ν</span>. como em Diod S 36, 8, 4; TestAbr A 9 p. 86, 17 [Stone p. 20]). <span class=\"greek\">ἐγενήθησαν</span> <span class=\"greek\">ὡς</span> <span class=\"greek\">νεκροί</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.28.4\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 28:4</a>. <span class=\"greek\">ἐγένετο</span> <span class=\"greek\">ὡσεὶ</span> <span class=\"greek\">νεκρός</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.9.26\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 9:26</a>. Acerca de Cristo, <span class=\"greek\">ἐγενόμην</span> <span class=\"greek\">ν</span>. estive morto <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.1.18\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 1:18</a>; cf. 2:8.</p><p class=\"entry-text\">② Relativo a uma deficiência moral ou espiritual tão grande que equivale à morte, morto, extensão figurada de 1.</p><p class=\"entry-text\">ⓐ De pessoas (Soph., Philoct. 1018 <span class=\"greek\">ἄφιλον</span> <span class=\"greek\">ἔρημον</span> <span class=\"greek\">ἄπολιν</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">ζῶσιν</span> <span class=\"greek\">νεκρόν</span>; Menand., Colax 50; Epict. 3, 23, 28; escólio de Aristoph., Ran. 423 <span class=\"greek\">διὰ</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">κακοπραγίαν</span> <span class=\"greek\">νεκροὺς</span> <span class=\"greek\">τοὺς</span> <span class=\"greek\">Ἀθηναίους</span> <span class=\"greek\">καλεῖ</span>; Sextus 175 <span class=\"greek\">ν</span>. <span class=\"greek\">παρὰ</span> <span class=\"greek\">θεῷ</span>; Philo, Leg. All. 3, 35, Conf. Lingu. 55, Fuga 56): acerca do filho pródigo, considerado morto, desaparecido, ou moralmente morto, depravado <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.15.24\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 15:24</a>, 32. De uma congregação inativa, negligente <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.3.1\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 3:1</a>. De pessoas antes do batismo Hs 9, 16, 3f; 6. Com dativo de desvantagem, <span class=\"greek\">ν</span>. <span class=\"greek\">τῇ</span> <span class=\"greek\">ἁμαρτίᾳ</span> morto para o pecado <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.6.11\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 6:11</a>.—<span class=\"greek\">ἐκ</span> <span class=\"greek\">νεκρῶν</span> <span class=\"greek\">ζῶντας</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.6.13\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 6:13</a>; analogamente, quanto ao significado do batismo, <span class=\"greek\">ν</span>. <span class=\"greek\">τοῖς</span> <span class=\"greek\">παραπτώμασιν</span> mortos em transgressões <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.2.1\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 2:1</a>, 5; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.2.13\" target=\"_blank\" rel=\"noopener noreferrer\">Col 2:13</a>. Acerca de cristãos de mentalidade mundana: <span class=\"greek\">τὸ</span> <span class=\"greek\">ἥμισυ</span> <span class=\"greek\">ν</span>. <span class=\"greek\">ἐστι</span> Hs 8, 8, 1 v.l.</p><p class=\"entry-text\">ⓑ De coisas: <span class=\"greek\">ν</span>. <span class=\"greek\">ἔργα</span> obras mortas, incapazes de produzir vida eterna <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.6.1\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 6:1</a>; 9:14; Hs 9, 21, 2. <span class=\"greek\">ἡ</span> <span class=\"greek\">πίστις</span> <span class=\"greek\">χωρὶς</span> <span class=\"greek\">ἔργων</span> <span class=\"greek\">ν</span>. <span class=\"greek\">ἐστιν</span> a fé sem obras (isto é, sem aplicação prática) está morta, é inútil <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.2.26\" target=\"_blank\" rel=\"noopener noreferrer\">Js 2:26</a>b (<span class=\"greek\">κενή</span> P74); cf. versículos 17, 20 v.l. (DVerseput, Reworking the Puzzle of Faith and Deeds in <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.2.14\" target=\"_blank\" rel=\"noopener noreferrer\">Js 2:14</a>–26: NTS 43, ’97, 97–115). Sobre o pecado: <span class=\"greek\">χωρὶς</span> <span class=\"greek\">νόμου</span> <span class=\"greek\">ἁμαρτία</span> <span class=\"greek\">ν</span>. onde não há lei, o pecado está morto, isto é, o pecado não é perceptível <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.7.8\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 7:8</a> (cf. 5:20). Sobre o crente em quem Cristo vive: <span class=\"greek\">τὸ</span> <span class=\"greek\">σῶμα</span> <span class=\"greek\">νεκρόν</span> o corpo (de <span class=\"greek\">σάρξ</span> e pecado) está morto 8:10 (Herm. Wr. 7, 2 denomina a corporeidade visível <span class=\"greek\">ὁ</span> <span class=\"greek\">αἰσθητικὸς</span> <span class=\"greek\">νεκρός</span>. Semelhantemente, Philo, Leg. All. 3, 69ff, Gig. 15).</p><p class=\"entry-text\">③ Relativo àquilo que nunca esteve vivo e carece da capacidade de viver, morto, inanimado (Wsd 15:5; Ar. 3:2; Just., A I, 9, 1 <span class=\"greek\">ἀψυχα</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">νεκρά</span>), acerca da serpente de bronze 12:7. Acerca de objetos politeístas de veneração cultual PtK 2 p. 14, 21. <span class=\"greek\">νεκροὶ</span> <span class=\"greek\">θεοί</span> deuses mortos 2 Cl 3:1; D 6:3. (Na fronteira entre 1 e 2: <span class=\"greek\">τὰ</span> <span class=\"greek\">μὲν</span> <span class=\"greek\">ὀνόματα</span> … <span class=\"greek\">θεῶν</span> <span class=\"greek\">ὀνόματά</span> <span class=\"greek\">ἐστιν</span> <span class=\"greek\">νεκρῶν</span> <span class=\"greek\">ἀνθρώπων</span> Theoph. Ant. 1, 9 [p. 76, 8]).</p><p class=\"entry-text\">B. Como substantivo, <span class=\"greek\">ὁ</span> <span class=\"greek\">ν</span>. (assim predominantemente desde Hom.; inscrições, papiros, LXX, En 103:5; TestGad 4:6; ApcEsdr 4:36; Philo; Jos., Bell. 4, 331 e outros; Ar. 15, 3; Just., Mel., Ath., título R.; Jos.).</p><p class=\"entry-text\">① Aquele que já não está fisicamente vivo, pessoa morta, corpo morto, cadáver, literalmente <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.7.15\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 7:15</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.9.17\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 9:17</a>; 11:35; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.20.5\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 20:5</a>; 12:13. <span class=\"greek\">μακάριοι</span> <span class=\"greek\">οἱ</span> <span class=\"greek\">ν</span>. <span class=\"greek\">οἱ</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">κυρίῳ</span> <span class=\"greek\">ἀποθνῄσκοντες</span> 14:13; cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.4.16\" target=\"_blank\" rel=\"noopener noreferrer\">1 Th 4:16</a>. Sem artigo, <span class=\"greek\">νεκροῦ</span> <span class=\"greek\">βληθέντος</span> AcPlCor 2:32 (com <span class=\"greek\">ζῶν</span> como em Appian, Liby. 129 §617 <span class=\"greek\">τ</span>. <span class=\"greek\">νεκροὺς</span> <span class=\"greek\">κ</span>. <span class=\"greek\">τ</span>. <span class=\"greek\">ζῶντας</span>; Aesop, Fab. 69 H.=288 P.; EpArist 146). De Deus: <span class=\"greek\">οὐκ</span> <span class=\"greek\">ἔστιν</span> (<span class=\"greek\">ὁ</span>) <span class=\"greek\">θεὸς</span> <span class=\"greek\">νεκρῶν</span> <span class=\"greek\">ἀλλὰ</span> <span class=\"greek\">ζώντων</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.22.32\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 22:32</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.12.27\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 12:27</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.20.38\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 20:38</a>. <span class=\"greek\">καὶ</span> <span class=\"greek\">ν</span>. <span class=\"greek\">καὶ</span> <span class=\"greek\">ζώντων</span> <span class=\"greek\">κυριεύειν</span> dominar vivos e mortos, isto é, toda a humanidade passada e presente <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.14.9\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 14:9</a>. <span class=\"greek\">κρίνειν</span> <span class=\"greek\">ζῶντας</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">νεκρούς</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TI.4.1\" target=\"_blank\" rel=\"noopener noreferrer\">2 Ti 4:1</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.4.5\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 4:5</a>; 7:2; <span class=\"greek\">κριτὴς</span> <span class=\"greek\">ζώντων</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ν</span>. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.10.42\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 10:42</a>; 2 Cl 1:1; Pol 2:1. Nessa combinação, <span class=\"greek\">ν</span>. sem artigo significa todos os mortos, todos os que estão no mundo inferior (<span class=\"greek\">νεκροί</span> = os mortos: Thu. 4, 14, 5; 5, 10, 12; Lucian, Ver. Hist. 1, 39; Polyaenus 4, 2, 5). Acerca de cristãos falecidos: <span class=\"greek\">νεκροῖς</span> <span class=\"greek\">εὐαγγελίσθη</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.4.6\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 4:6</a> (Selwyn, comm. 337–39). O artigo também pode ocorrer sem significado especial: <span class=\"greek\">ὁ</span> <span class=\"greek\">καιρὸς</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">ν</span>. <span class=\"greek\">κριθῆναι</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.11.18\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 11:18</a>; <span class=\"greek\">οἱ</span> <span class=\"greek\">ν</span>. <span class=\"greek\">ἀκούσουσιν</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">φωνῆς</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">υἱοῦ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">θεοῦ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.5.25\" target=\"_blank\" rel=\"noopener noreferrer\">J 5:25</a>. Em locuções prepositivas, frequentemente sem artigo: <span class=\"greek\">ἐκ</span>. <span class=\"greek\">ν</span>. e <span class=\"greek\">ἀπὸ</span> <span class=\"greek\">ν</span>. (B-D-F §254, 2; Rob. 791f). <span class=\"greek\">ἐγείρειν</span> <span class=\"greek\">ἐκ</span> <span class=\"greek\">ν</span>., <span class=\"greek\">ἐγείρεσθαι</span> <span class=\"greek\">ἐκ</span> <span class=\"greek\">ν</span>. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.17.9\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 17:9</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.6.14\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 6:14</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.9.7\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 9:7</a>; 24:46; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.2.22\" target=\"_blank\" rel=\"noopener noreferrer\">J 2:22</a>; 12:1, 9, 17; 21:14; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.3.15\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 3:15</a>; 4:10; 13:30; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.4.24\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 4:24</a>; 6:4, 9; 7:4; 8:11ab, 34 v.l.; 10:9; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.15.12\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 15:12</a>a, 20; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.1.1\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 1:1</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.1.20\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 1:20</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.2.12\" target=\"_blank\" rel=\"noopener noreferrer\">Col 2:12</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TI.2.8\" target=\"_blank\" rel=\"noopener noreferrer\">2 Ti 2:8</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.11.19\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 11:19</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.1.21\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 1:21</a>; IMg 9:3; ITr 9:2; Pol 2:1f; 5:2; AcPlCor 2:6; 5:2. <span class=\"greek\">ἀναστῆναι</span> <span class=\"greek\">ἐκ</span> <span class=\"greek\">ν</span>. e <span class=\"greek\">ἀναστῆσαί</span> <span class=\"greek\">τινα</span> <span class=\"greek\">ἐκ</span> <span class=\"greek\">ν</span>. (Just.; Mel., P.) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.9.9\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 9:9</a>f; 12:25; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.16.31\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 16:31</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.20.9\" target=\"_blank\" rel=\"noopener noreferrer\">J 20:9</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.10.41\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 10:41</a>; 13:34; 17:3, 31; 1 Cl 24:1; 15:9; GPt 8:30 (KKuhn, NTS 7, ’61, 343f); Papias (11:3); Qua. <span class=\"greek\">ἡ</span> <span class=\"greek\">ἐκ</span> <span class=\"greek\">ν</span>. <span class=\"greek\">ἀνάστασις</span> (Mel., P. 3, 20) 5:6; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.20.35\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 20:35</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.4.2\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 4:2</a>. Também <span class=\"greek\">ἡ</span> <span class=\"greek\">ἐξανάστασις</span> <span class=\"greek\">ἡ</span> <span class=\"greek\">ἐκ</span> <span class=\"greek\">ν</span>. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.3.11\" target=\"_blank\" rel=\"noopener noreferrer\">Phil 3:11</a>; <span class=\"greek\">ζωὴ</span> <span class=\"greek\">ἐκ</span> <span class=\"greek\">ν</span>. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.11.15\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 11:15</a>; <span class=\"greek\">ἀνάγειν</span> <span class=\"greek\">ἐκ</span> <span class=\"greek\">ν</span>. (Just., A I, 45, 1; 50, 12 e outros), fazer subir do reino dos mortos <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.10.7\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 10:7</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.13.20\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 13:20</a>. <span class=\"greek\">ἀπὸ</span> <span class=\"greek\">ν</span>. <span class=\"greek\">πορεύεσθαι</span> <span class=\"greek\">πρός</span> <span class=\"greek\">τινα</span> vir do reino dos mortos até alguém <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.16.30\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 16:30</a>. Às vezes o artigo é incluído nessas combinações prepositivas sem diferença apreciável de sentido: <span class=\"greek\">ἐγείρεσθαι</span> <span class=\"greek\">ἀπὸ</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">ν</span>. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.14.2\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 14:2</a>; 27:64; 28:7 (mas <span class=\"greek\">ἐγείρεσθαι</span> <span class=\"greek\">ἐκ</span> <span class=\"greek\">ν</span>. 17:9). <span class=\"greek\">ἐγείρειν</span> <span class=\"greek\">ἐκ</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">ν</span>. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.1.10\" target=\"_blank\" rel=\"noopener noreferrer\">1 Th 1:10</a> v.l.; <span class=\"greek\">πρωτότοκος</span> <span class=\"greek\">ἐκ</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">ν</span>. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.1.18\" target=\"_blank\" rel=\"noopener noreferrer\">Col 1:18</a>, ao lado de <span class=\"greek\">ὁ</span> <span class=\"greek\">πρωτότοκος</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">ν</span>. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.1.5\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 1:5</a>. O artigo muitas vezes se omite com o genitivo; assim ocorre, em regra, em <span class=\"greek\">ἀνάστασις</span> <span class=\"greek\">ν</span>. (Did., Gen. 96, 13), ressurreição dos mortos, expressão explicada pela locução <span class=\"greek\">ἀναστῆναι</span> <span class=\"greek\">ἐκ</span> <span class=\"greek\">ν</span>. (também Ar. 15, 3; Just., D. 80, 4) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.17.32\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 17:32</a>; 23:6; 24:21; 26:23; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.1.4\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 1:4</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.15.12\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 15:12</a>b, 13, 21; D 16:6. <span class=\"greek\">νεκροῦ</span> <span class=\"greek\">ἀνάστασιν</span> Papias (2:9). <span class=\"greek\">ἀνάστασις</span> <span class=\"greek\">ἐκ</span> <span class=\"greek\">ν</span>. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.1.3\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 1:3</a>; <span class=\"greek\">ἐκ</span> <span class=\"greek\">ν</span>. <span class=\"greek\">ἀνάστασις</span> AcPlCor 2:35. Também <span class=\"greek\">ἀνάστασις</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">ν</span>. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.22.31\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 22:31</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.15.42\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 15:42</a> (Just., D. 45, 2). <span class=\"greek\">νεκροὺς</span> <span class=\"greek\">ἐγείρειν</span> ressuscitar mortos <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.10.8\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 10:8</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.26.8\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 26:8</a>; AcPl Ha 8, 35=BMM verso 8f. Voz passiva (Theoph. Ant. 1, 8 [p. 74, 6]) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.11.5\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 11:5</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.7.22\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 7:22</a> (cf. 4Q 521:12; para a compreensão figurada, ver <span class=\"greek\">κωφός</span> 2); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.15.15\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 15:15</a>f, 29b, 32. Também <span class=\"greek\">τοὺς</span> <span class=\"greek\">ν</span>. <span class=\"greek\">ἐγείρειν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.5.21\" target=\"_blank\" rel=\"noopener noreferrer\">J 5:21</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.1.9\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 1:9</a>. Voz passiva <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.12.26\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 12:26</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.20.37\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 20:37</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.15.35\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 15:35</a>, 52. Acerca de Deus, <span class=\"greek\">ζωοποιεῖν</span> <span class=\"greek\">τοὺς</span> <span class=\"greek\">ν</span>. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.4.17\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 4:17</a>. <span class=\"greek\">μετὰ</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">ν</span>. entre os mortos <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.24.5\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 24:5</a>. <span class=\"greek\">βαπτίζεσθαι</span> <span class=\"greek\">ὑπὲρ</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">ν</span>. ser batizado em favor dos mortos <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.15.29\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 15:29</a>a (ver <span class=\"greek\">βαπτίζω</span> 2c; JWhite, JBL 116, 97, 487–99). <span class=\"greek\">τάφοι</span> <span class=\"greek\">νεκρῶν</span> IPhld 6:1. <span class=\"greek\">ὀστέα</span> <span class=\"greek\">νεκρῶν</span> os ossos dos mortos <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.23.27\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 23:27</a>. <span class=\"greek\">ἄτονος</span> <span class=\"greek\">ὥσπερ</span> <span class=\"greek\">νεκροῦ</span> <span class=\"greek\">νεῦρα</span> sem forças como os tendões de um cadáver Hm 12, 6, 2. <span class=\"greek\">αἷμα</span> <span class=\"greek\">ὡς</span> <span class=\"greek\">νεκροῦ</span> sangue como o de um morto <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.16.3\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 16:3</a>.</p><p class=\"entry-text\">② Aquele que é tão insensível espiritualmente que equivale a um morto, pessoa morta, extensão figurada de 1 (cf. Philo, Fuga 56): <span class=\"greek\">ἄφες</span> <span class=\"greek\">τοὺς</span> <span class=\"greek\">ν</span>. <span class=\"greek\">θάψαι</span> <span class=\"greek\">τοὺς</span> <span class=\"greek\">ἑαυτῶν</span> <span class=\"greek\">ν</span>. deixa que os mortos sepultem os seus mortos, a respeito daqueles que não dão prioridade ao discipulado <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.8.22\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 8:22</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.9.60\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 9:60</a> (cf. Theophyl. Sim., Ep. 25 <span class=\"greek\">τ</span>. <span class=\"greek\">θνητοῖς</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">θνητὰ</span> <span class=\"greek\">καταλείψομεν</span>.—FPerles, ZNW 19, 1920, 96; 25, 1926, 286f; Bleibtreu [ver <span class=\"greek\">μισέω</span> 2]. AEhrhardt, Studia Theologica VI, 2, ’53, 128–64.—<span class=\"greek\">θάπτειν</span> <span class=\"greek\">τοὺς</span> <span class=\"greek\">ν</span>. literalmente Jos., Bell. 5, 518). As palavras <span class=\"greek\">ἀνάστα</span> <span class=\"greek\">ἐκ</span> <span class=\"greek\">τ</span>. <span class=\"greek\">νεκρῶν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.5.14\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 5:14</a> parecem pertencer a um hino (ver Rtzst., Erlösungsmyst. 1921, 136) que talvez tenha passado a fazer parte do ritual batismal (MDibelius, Hdb. ad loc.; FDölger, Sol Salutis2, 1925, 364ff).—B. 290. DELG. M-M. EDNT. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0243-09\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">νεκροφόρος, ον</h1><div class=\"entry-meta\"><span>adjetivo e substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">νεκροφόρος</span>, <span class=\"greek\">ον</span> (<span class=\"greek\">νεκρός</span>, <span class=\"greek\">φέρω</span>), que transporta um cadáver; como substantivo, <span class=\"greek\">ὁ</span> <span class=\"greek\">ν</span>., aquele que transporta o cadáver. Literalmente, significa homem que leva um cadáver até o lugar de sepultamento (Polyb., 35, 6, 2=Plut., Cato Maj. 341 [9, 2]). Ign. emprega o termo num jogo de palavras para refutar as opiniões dos docetistas, que negam que Cristo tenha sido <span class=\"greek\">σαρκοφόρος</span>. Quem assim procede, afirma, é ele próprio um <span class=\"greek\">νεκροφόρος</span>, evidentemente no sentido de estar revestido de um cadáver em vez de carne ISm 5:2 (cf. Philo, Agr. 25 [<span class=\"greek\">ψυχὴ</span>] <span class=\"greek\">νεκροφοροῦσα</span>).—DELG s.v. <span class=\"greek\">φέρω</span> D2.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0243-10\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">νεκρόω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">νεκρόω</span> (<span class=\"greek\">νεκρός</span>), 1º aoristo <span class=\"greek\">ἐνέκρωσα</span>; particípio perfeito passivo <span class=\"greek\">νενεκρωμένος</span> (vocábulo helenístico: Hipponax[?, ver abaixo]; Epict. 1, 5, 7; Plut., Mor. 954d; Themist., Paraphr. Aristot. II p. 51, 15 Spengel; inscrições; Philo, Aet. M. 125; Just., A I, 18, 6; Ath., R. 24 p. 78, 20 e outros), amortecer ou fazer cessar por completo, fazer morrer, extensão figurada do sentido primário «pôr fim à vida de algo, fazer que esteja morto»: <span class=\"greek\">τὰ</span> <span class=\"greek\">μέλη</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">γῆς</span> aquilo que é terreno em vós <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.3.5\" target=\"_blank\" rel=\"noopener noreferrer\">Col 3:5</a>. Voz passiva: estar praticamente morto (Longus 2, 7, 5): <span class=\"greek\">νενεκρωμένος</span>, desgastado, impotente, a respeito de pessoas cujas capacidades físicas falharam em determinado aspecto (comentário sobre Hipponax POxy 2176 Fgm. 1 II, 7f=Hipponax Fgm. 129 C, 7f p. 137 Degani <span class=\"greek\">νενε</span>]<span class=\"greek\">κρῶσθαι</span>, mas <span class=\"greek\">ἀπονε</span>‹<span class=\"greek\">νε</span>›]<span class=\"greek\">κρῶσθαι</span> p. 153 West [quanto ao fragmento reconstruído de Hipponax com base no comentário, ver Fgm. X Diehl3; 129a–e Degani]; Maximus Tyr. 41, 3h; cf. Epict. 4, 5, 21); por exemplo, de Abraão em sua velhice: <span class=\"greek\">ἀφ</span>’ <span class=\"greek\">ἑνὸς</span> <span class=\"greek\">ἐγενήθησαν</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ταῦτα</span> <span class=\"greek\">νενεκρωμένου</span> de um só homem, e este já praticamente morto, nasceram <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.11.12\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 11:12</a>. <span class=\"greek\">τὸ</span> <span class=\"greek\">σῶμα</span> <span class=\"greek\">νενεκρωμένον</span> seu corpo já debilitado <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.4.19\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 4:19</a> (cf. IG III/2, 1355 <span class=\"greek\">ἄνθρωπε</span> <span class=\"greek\">μή</span> <span class=\"greek\">μου</span> <span class=\"greek\">παρέλθῃς</span> <span class=\"greek\">σῶμα</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">νενεκρωμένον</span>.—Dssm., LO 75 [LAE 94]; BHaensler, BZ 12, 1914, 168ff; 14, 1916, 164ff).—DELG s.v. <span class=\"greek\">νεκρός</span>. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0243-11\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">νέκρωσις, εως, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">νέκρωσις</span>, <span class=\"greek\">εως</span>, <span class=\"greek\">ἡ</span> (<span class=\"greek\">νεκρόω</span>; Aretaeus p. 32, 16; Soranus p. 140, 3; Galen: CMG V/9, 2 p. 87, 10; 313, 16 <span class=\"greek\">ν</span>. <span class=\"greek\">τοῦ</span> <span class=\"greek\">σώματος</span>; Porphyr., Abst. 4, 20 p. 262, 20 Nauck; Proclus sobre Pla., Rep. 2, 117, 16 Kr. acerca das árvores na primavera: <span class=\"greek\">ἐκτινάσσειν</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">ν</span>.; Photius, Bibl. 513, 36 <span class=\"greek\">οἱ</span> <span class=\"greek\">γὰρ</span> <span class=\"greek\">κόκκοι</span> <span class=\"greek\">μετὰ</span> <span class=\"greek\">τ</span>. <span class=\"greek\">νέκρωσιν</span> <span class=\"greek\">ἀναζῶσι</span>).</p><p class=\"entry-text\">① Morte enquanto processo, morte, ato de fazer morrer (Iren. 3, 18, 3 [Harv. II 97, 4]), literalmente: <span class=\"greek\">πάντοτε</span> <span class=\"greek\">τ</span>. <span class=\"greek\">νέκρωσιν</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">Ἰησοῦ</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">σώματι</span> <span class=\"greek\">περιφέροντες</span> levamos sempre em nosso corpo o ato de fazer morrer Jesus (referência ao perigo constante de morte em que vive o apóstolo em razão de sua dedicação a Jesus) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.4.10\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 4:10</a>.</p><p class=\"entry-text\">② Cessação de um estado ou atividade, estado de morte, mortificação, extensão figurada de 1 (cf. definição de <span class=\"greek\">νεκρόω</span>).</p><p class=\"entry-text\">ⓐ Do estado de incapacidade de gerar filhos em razão da menopausa: <span class=\"greek\">ἡ</span> <span class=\"greek\">ν</span>. <span class=\"greek\">τῆς</span> <span class=\"greek\">μήτρας</span> <span class=\"greek\">Σάρρας</span> a mortificação do ventre de Sara <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.4.19\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 4:19</a>.</p><p class=\"entry-text\">ⓑ De uma vida ineficaz ou inútil: <span class=\"greek\">ἀποτίθεσθαι</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">ν</span>. <span class=\"greek\">τῆς</span> <span class=\"greek\">ζωῆς</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">προτέρας</span> abandonar o estado de morte de sua vida anterior, isto é, a vida morta que antes levavam (antes do batismo) Hs 9, 16, 2f. <span class=\"greek\">νέκρωσις</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">καρδίας</span> entorpecimento do coração <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.3.5\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 3:5</a> D (cf. Epict. 1, 5, 4 <span class=\"greek\">ἀπονέκρωσις</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">ψυχῆς</span>).—DELG s.v. <span class=\"greek\">νεκρός</span>. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0243-12\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">νέμω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">νέμω</span> (Hom. e outros, com sentidos diversos; Jos., Ant. 17, 193, C. Apion 1, 60, «cuidar»; ApcEsdr 7:1 p. 33, 2 Tdf., «distribuir»), em nossa literatura somente médio-passivo <span class=\"greek\">νέμομαι</span>; imperfeito <span class=\"greek\">ἐνεμόμην</span>; futuro <span class=\"greek\">νεμήσομαι</span> LXX; aoristo, 3ª pessoa do plural, <span class=\"greek\">ἐνημήθησαν</span> Wsd 19:9, acerca de animais que comem ao se deslocarem por espaços abertos: pastar, alimentar-se (assim em Hom. e outros; papiros, LXX, Jos., Bell. 6, 155), de gado e aves: <span class=\"greek\">εἰς</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">ὄρος</span> pastar na montanha Hs 9, 1, 8. Acerca de Maria: <span class=\"greek\">ὡς</span> <span class=\"greek\">περιστερὰ</span> <span class=\"greek\">νεμομένη</span> obtendo alimento como uma pomba GJs 8:1. Transitivo, <span class=\"greek\">ν</span>. <span class=\"greek\">τι</span> alimentar-se de algo 9, 24, 1.—DELG. Sv.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0243-13\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">νεομηνία, ας, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">νεομηνία</span>, <span class=\"greek\">ας</span>, <span class=\"greek\">ἡ</span> (<span class=\"greek\">νέος</span>, <span class=\"greek\">μήν</span>; na forma contraída <span class=\"greek\">νουμηνία</span> [<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.2.16\" target=\"_blank\" rel=\"noopener noreferrer\">Col 2:16</a> Tdf.; PKatz, Kratylos 5, ’60, 158] desde Aristoph.; X., An. 5, 6, 23; Antig. Car. 126; Appian, Bell. Civ. 5, 97 §404; 98 §406; inscrições [índices SIG e OGI]; PPetr II, 4, col. 2, 6 [III b.c.]; BGU 1053, 20 [13 b.c.]; LXX [Thackeray 98]; Philo; Jos., Bell. 5, 230, Ant. 4, 78. A forma não contraída [jônica] não é encontrada nas inscrições [Nachmanson 69] e nos papiros [PTebt 318, 12: 166 a.d.; BGU 859, 6: II a.d.. Ver Mayser p. 153] antes da segunda metade do segundo século a.d.; também Alciphron 3, 25, 2.—Proclus sobre Pla., Cratyl. p. 40, 3 P. <span class=\"greek\">νουμηνίαν</span> <span class=\"greek\">μὲν</span> <span class=\"greek\">Ἀττικοί</span> <span class=\"greek\">φασιν</span>, <span class=\"greek\">νεομηνίαν</span> <span class=\"greek\">δὲ</span> <span class=\"greek\">Κρῆτες</span>; Lob., Phryn. 148; sobre a leitura anacrônica em N. [sem variante de leitura], ver M-M e New Docs 3, 76f com outros papiros), lua nova, primeiro dia do mês, frequentemente celebrado como festividade por judeus e gentios: <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.2.16\" target=\"_blank\" rel=\"noopener noreferrer\">Col 2:16</a>; B 2:5; 15:8 (os dois últimos Is 1:13 <span class=\"greek\">νουμηνία</span>); PtK 2 p. 14, 28. <span class=\"greek\">τὴν</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">νουμηνίας</span> <span class=\"greek\">εἰρωνείαν</span> a observância fingida da lua nova Dg 4:1 (Antig. Car. 126 <span class=\"greek\">μύρμηκες</span> <span class=\"greek\">ταῖς</span> <span class=\"greek\">νουμηνίαις</span> <span class=\"greek\">ἀναπαύονται</span> = as formigas descansam na época da lua nova).—M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0243-14\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">νέος, α, ον</h1><div class=\"entry-meta\"><span>adjetivo e substantivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">νέος</span>, <span class=\"greek\">α</span>, <span class=\"greek\">ον</span> (Hom. e posteriores; inscrições, papiros, LXX, TestSol; TestAbr A 2 p. 78, 27 [Stone p. 4]; Test12Patr; JosAs 29:11 cód. A [p. 85, 15 Bat. comp.]; ApcEsdr 5:5 p. 29, 29 Tdf.; ApcSed 16:2; AscIs 3:3 [comp.]; Philo, Joseph.; apologistas, exceto Ar.), comparativo <span class=\"greek\">νεώτερος</span>.</p><p class=\"entry-text\">① Relativo a algo existente há relativamente pouco tempo, novo, fresco.</p><p class=\"entry-text\">ⓐ De coisas: <span class=\"greek\">ν</span>. <span class=\"greek\">φύραμα</span> massa fresca, sem fermento; simbolicamente, acerca de cristãos <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.5.7\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 5:7</a> (ver <span class=\"greek\">φύραμα</span>, <span class=\"greek\">ζύμη</span>). Também <span class=\"greek\">ν</span>. <span class=\"greek\">ζύμη</span> acerca de Cristo IMg 10:2. <span class=\"greek\">οἶνος</span> <span class=\"greek\">ν</span>. vinho novo (Simonides 49 D.; Diocles 141 p. 184, 14; POxy 729, 19; 92, 2; 3; Sir 9:10), ainda em fermentação <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.9.17\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 9:17</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.2.22\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 2:22</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.5.37\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 5:37</a>f; (em oposição a <span class=\"greek\">παλαιὸς</span> <span class=\"greek\">οἶ</span>., vinho velho, envelhecido: escólio sobre Pind., O. 9, 74f [49]) em contraste com 39.—HImmerwahr, New Wine in Ancient Wineskins: Hesperia 61, ’92, 121–32.</p><p class=\"entry-text\">ⓑ Figuradamente, de Cristo: <span class=\"greek\">πάντοτε</span> <span class=\"greek\">νέος</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">ἁγίων</span> <span class=\"greek\">καρδίαις</span> <span class=\"greek\">γεννώμενος</span> ele nasce sempre de novo no coração do povo de Deus Dg 11:4 (Diod S 3, 62, 6, acerca de Dioniso, despedaçado, mas depois novamente reunido por Deméter: <span class=\"greek\">ἐξ</span> <span class=\"greek\">ἀρχῆς</span> <span class=\"greek\">νέον</span> <span class=\"greek\">γεννηθῆναι</span>).</p><p class=\"entry-text\">② Relativo à superioridade de qualidade ou condição em comparação com o que existia anteriormente, novo, acerca de pessoas: <span class=\"greek\">ἐνδύσασθαι</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">ν</span>. (<span class=\"greek\">ἄνθρωπον</span>) revestir-se da nova pessoa <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.3.10\" target=\"_blank\" rel=\"noopener noreferrer\">Col 3:10</a>. <span class=\"greek\">διαθήκη</span> <span class=\"greek\">ν</span>. a nova aliança (<span class=\"greek\">διαθήκη</span> 2; <span class=\"greek\">λόγος</span> Mel., P. 6, 44) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.12.24\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 12:24</a>.</p><p class=\"entry-text\">③ Relativo aos estágios iniciais da vida, jovem.</p><p class=\"entry-text\">ⓐ Como adjetivo:</p><p class=\"entry-text\"><span class=\"greek\">α</span>. Positivo (Appian, Bell. Civ. 5, 136 §566 <span class=\"greek\">νέος</span> <span class=\"greek\">ἀνήρ</span>; PsSol 2:8; 17:11; Philo, Post. Cai. 109; Jos., Ant. 8, 23; inscrição de Jerusalém: SEG VIII, 209 [I a.d.]) <span class=\"greek\">ὁλοτελῶς</span> <span class=\"greek\">νέον</span> <span class=\"greek\">εἶναι</span> ser inteiramente jovem Hv 3, 13, 4. Também acerca de animais: <span class=\"greek\">μόσχος</span> <span class=\"greek\">νέος</span> boi jovem ou bezerro 1 Cl 52:2 (Ps 68:32).</p><p class=\"entry-text\"><span class=\"greek\">β</span>. Predominantemente no comparativo: <span class=\"greek\">ὁ</span> <span class=\"greek\">νεώτερος</span> <span class=\"greek\">υἱός</span> o filho mais novo (Gen 27:15; cf. Philo, Sacr. Abel. 42; Jos., Ant. 12, 235; em todas essas passagens em oposição a <span class=\"greek\">πρεσβύτερος</span>, como em <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.15.25\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 15:25</a>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.15.13\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 15:13</a>; cf. versículo 12; 13:5 (Gen 48:14). <span class=\"greek\">τὴν</span> <span class=\"greek\">ὄψιν</span> <span class=\"greek\">νεωτέραν</span> <span class=\"greek\">ἔχειν</span> ter uma aparência mais jovem Hv 3, 10, 4; 3, 12, 1. <span class=\"greek\">ὡσεὶ</span> <span class=\"greek\">νεώτερος</span> <span class=\"greek\">ἐγεγόνειν</span> senti-me novamente jovem Hs 9, 11, 5. Por outro lado, o sentido comparativo quase já não é percebido em 3, 10, 5; 3, 13, 1. Da mesma forma, em <span class=\"greek\">νεώτεραι</span> <span class=\"greek\">χῆραι</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.5.11\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ti 5:11</a>; cf. versículo 14, onde o substantivo deve ser suprido pelo contexto. Semelhantemente em <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.21.18\" target=\"_blank\" rel=\"noopener noreferrer\">J 21:18</a> (cf. Ps 36:25).</p><p class=\"entry-text\">ⓑ Como substantivo:</p><p class=\"entry-text\"><span class=\"greek\">α</span>. Positivo: (<span class=\"greek\">οἱ</span>) <span class=\"greek\">νέοι</span> os jovens (X., Cyr. 5, 1, 25; Diod S 14, 115, 3; 2 Macc 5:13; 6:28; 15:17; Jos., C. Ap. 2, 206; Just., A I, 54, 1; Tat. 32, 2; Ath. 34, 1; sobre o sentido não técnico, ver CForbes, NEOI ’33, 5 n. 17), com <span class=\"greek\">οἱ</span> <span class=\"greek\">πρεσβύτεροι</span> (ver <span class=\"greek\">πρεσβύτερος</span> 1a) 1 Cl 1:3; 3:3; 21:6. <span class=\"greek\">σκοπὸν</span> <span class=\"greek\">πᾶσι</span> <span class=\"greek\">τοῖς</span> <span class=\"greek\">νέοις</span> <span class=\"greek\">τιθέναι</span> estabelecer um objetivo para todos os jovens 2 Cl 19:1 (<span class=\"greek\">οἱ</span> <span class=\"greek\">νέοι</span> para pessoas jovens de ambos os sexos: Nicetas Eugen. 8, 187 H.). AcPl Ox 6, 23 (restaurado=Aa 1, 242, 2)—<span class=\"greek\">αἱ</span> <span class=\"greek\">νέαι</span> as jovens mulheres <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/TIT.2.4\" target=\"_blank\" rel=\"noopener noreferrer\">Tit 2:4</a>.</p><p class=\"entry-text\"><span class=\"greek\">β</span>. Comparativo, predominantemente com pouca força comparativa (POxy 298, 29; TestSol 1:2 L, 3 L, 4 L; Jos., Ant. 15, 407): <span class=\"greek\">οἱ</span> <span class=\"greek\">νεώτεροι</span> homens jovens (Diod S 14, 113, 3 [alternando com <span class=\"greek\">οἱ</span> <span class=\"greek\">νέοι</span>, sem diferença de sentido em 14, 115, 3, assim como 18, 46, 3 <span class=\"greek\">οἱ</span> <span class=\"greek\">πρεσβύτεροι</span> … <span class=\"greek\">οἱ</span> <span class=\"greek\">νεώτεροι</span> ao lado de 4 <span class=\"greek\">οἱ</span> <span class=\"greek\">πρεσβύτεροι</span> … <span class=\"greek\">οἱ</span> <span class=\"greek\">νέοι</span>]; 2 Macc 5:24; Just., D. 131, 6; MartIs 3:3 [Denis p. 112, Amh.] sing.) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.5.6\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 5:6</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.5.1\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ti 5:1</a> (ver <span class=\"greek\">πρεσβύτερος</span> 1a); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/TIT.2.6\" target=\"_blank\" rel=\"noopener noreferrer\">Tit 2:6</a>; Pol 5:3. Em oposição a <span class=\"greek\">πρεσβύτεροι</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.5.5\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 5:5</a> (X., An. 7, 4, 5; Timaeus Hist.: 566 Fgm. 11a Jac. <span class=\"greek\">διακονεῖν</span> <span class=\"greek\">τοὺς</span> <span class=\"greek\">νεωτέρους</span> <span class=\"greek\">τοῖς</span> <span class=\"greek\">πρεσβυτέροις</span>; Dio Chrys. 78 [29], 21; Demosth., Ep. 2, 10; EpArist 14; Philo, Spec. Leg. 2, 226; Jos., Ant. 3, 47; PParis 66, 24 <span class=\"greek\">πρεσβύτεροι</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ἀδύνατοι</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">νεώτεροι</span>; Plut., Mor. 486 F. Por outro lado, também a inscrição de Ptolemais APF 1, 1901, 202 no. 4, 15 <span class=\"greek\">οἱ</span> <span class=\"greek\">νεώτεροι</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">οἱ</span> <span class=\"greek\">ἄλλοι</span> <span class=\"greek\">πολῖται</span>. Sobre <span class=\"greek\">νεώτεροι</span> como termo técnico, ver Forbes, [<span class=\"greek\">α</span> acima] 60f; Schürer III 103). (<span class=\"greek\">αἱ</span>) <span class=\"greek\">νεώτεραι</span> mulheres jovens (ou mais jovens) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.5.2\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ti 5:2</a>.—<span class=\"greek\">ὁ</span> <span class=\"greek\">νεώτερος</span> ao lado de <span class=\"greek\">ὁ</span> <span class=\"greek\">μείζων</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.22.26\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 22:26</a> tem força de superlativo (cf. Gen 42:20); isso é influenciado pelo fato de que cabia ao mais jovem executar o serviço mais humilde (cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.5.6\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 5:6</a>).</p><p class=\"entry-text\">④ Pessoa que começa a experimentar algo, noviço, substantivo: <span class=\"greek\">νέοι</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">πίστει</span> Hv 3, 5, 4.</p><p class=\"entry-text\">⑤ O conhecido nome de cidade (atestável em Hdt. e outros) provavelmente deve ser escrito <span class=\"greek\">Νέα</span> <span class=\"greek\">πόλις</span> (cf. SIG 107, 35 [410/409 b.c.] <span class=\"greek\">ἐν</span> <span class=\"greek\">Νέαι</span> <span class=\"greek\">πόληι</span>; Meisterhans3-Schw. p. 137; PWarr 5, 8 [154 a.d.]; Diod S 20, 17, 1 <span class=\"greek\">Νέαν</span> <span class=\"greek\">πόλιν</span>; 20, 44, 1 <span class=\"greek\">ἐν</span> <span class=\"greek\">Νέᾳ</span> <span class=\"greek\">πόλει</span>; Jos., Bell. 4, 449. Mesmo em 247 a.d. aparece <span class=\"greek\">τῆς</span> <span class=\"greek\">Νέας</span> <span class=\"greek\">πόλεως</span> em papiros [PViereck, Her 27, 1892, 516 II, 29f]; W-S. §5, 7i; Mlt-H. 278; Hemer, Acts 113), acusativo <span class=\"greek\">Νέαν</span> <span class=\"greek\">πόλιν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.16.11\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 16:11</a> (variante de leitura <span class=\"greek\">Νεάπολιν</span>); IPol 8:1 (onde, não obstante, <span class=\"greek\">Νεάπολιν</span> está atestado e habitualmente é impresso). Em ambas as passagens, nossa literatura designa por Neápolis («Cidade Nova», atual Kavala) o porto de Filipos na Macedônia (Ptolem. 3, 13; Strabo 7, Fgm. 36 p. 331; Appian, Bell. Civ. 4, 106 §446; Pliny, NH 4, 42 p. 58 Detl.; ver PECS 614; PCollart, Philippes ’37, 102–32, esp. p. 104).—RHarrisville s.v. <span class=\"greek\">καινός</span>; Kl. Pauly IV 29f; B. 957f. Schhmidt, Syn. II 94–123 (sinônimos de <span class=\"greek\">καινός</span>). DELG. M-M. EDNT. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0243-15\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">νεοσσός</h1><div class=\"entry-meta\"><span>remissão</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">νεοσσός</span>: ver <span class=\"greek\">νοσσός</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0243-16\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">νεότης, τητος, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">νεότης</span>, <span class=\"greek\">τητος</span>, <span class=\"greek\">ἡ</span> (<span class=\"greek\">νέος</span>; Hom. e outros; inscrições, papiros, LXX; TestAbr B 10 p. 115, 8 [Stone p. 78]; Test12Patr; JosAs 17:4 [cód. A, com maior frequência: p. 64:18 e 72:15 Bat.]; Philo; Jos., Vi. 325), condição de ser jovem, juventude. <span class=\"greek\">τῆς</span> <span class=\"greek\">ν</span>. <span class=\"greek\">τινος</span> <span class=\"greek\">καταφρονεῖν</span> menosprezar a juventude de alguém, isto é, menosprezar alguém porque é jovem <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.4.12\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ti 4:12</a> (Appian, Bell. Civ. 1, 94 §435 <span class=\"greek\">ἐπιγελάω</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">νεότητι</span>). <span class=\"greek\">ἀπὸ</span> <span class=\"greek\">νεότητος</span> desde a juventude (M. Ant. 8, 1, 1; PTebt 276, 38; Jos., Bell. 4, 33; 1 Macc 1:6; 16:2, e empregado com genitivo Num 22:30; Jer 3:25) 1 Cl 63:3; 19:5; D 4:9. Também <span class=\"greek\">ἐκ</span> <span class=\"greek\">ν</span>. (Il. 14, 86; Gen 48:15; Is 47:15; 54:6 e muitíssimo frequentemente na LXX com genitivo) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.19.20\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 19:20</a> D; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.18.21\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 18:21</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.26.4\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 26:4</a>. <span class=\"greek\">ἐκ</span> <span class=\"greek\">νεότητός</span> <span class=\"greek\">μου</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.19.20\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 19:20</a> v.l.; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.10.20\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 10:20</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.18.21\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 18:21</a> v.l.—Leitura incerta <span class=\"greek\">νε</span>̣<span class=\"greek\">ό</span>̣<span class=\"greek\">τη</span>̣<span class=\"greek\">τ</span>̣<span class=\"greek\">α</span>̣ (a edição sugere que <span class=\"greek\">νηστείαν</span> teria mais sentido, mas não corresponde tão bem à leitura) AcPl Ha 6, 19.—DELG s.v. <span class=\"greek\">νέος</span> 6. M-M. EDNT.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0243-17\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">νεόφυτος, ον</h1><div class=\"entry-meta\"><span>adjetivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">νεόφυτος</span>, <span class=\"greek\">ον</span> (<span class=\"greek\">νέος</span>, <span class=\"greek\">φύω</span>; Aristoph., Fgm. 828 I p. 581 Kock; PRyl 138, 9 [34 a.d.]; BGU 563 I, 9 e outros [Dssm., NB 47f—BS 220f]; Ps 127:3; 143:12; Is 5:7; Job 14:9; JosAs 25:2), literalmente «recém-plantado»; figuradamente (somente na literatura cristã), recém-plantado na comunidade cristã, recém-convertido (cf. «neófito») <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.3.6\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ti 3:6</a>.—DELG s.v. <span class=\"greek\">νέος</span> C1. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0243-18\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">νέρτερος, α, ον</h1><div class=\"entry-meta\"><span>adjetivo comparativo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">νέρτερος</span>, <span class=\"greek\">α</span>, <span class=\"greek\">ον</span> (cf. <span class=\"greek\">ἔνερθε</span>, «de baixo»; Trag. e outros), comparativo sem positivo, relativo a uma posição inferior numa escala de extensão, mais baixo, inferior; geralmente com sentido positivo: pertencente ao mundo inferior. (<span class=\"greek\">τὰ</span>) <span class=\"greek\">νέρτερα</span> o mundo inferior (Orph. Hymns 3, 10; 57, 2; 78, 5 Qu.). <span class=\"greek\">νερτέρων</span> <span class=\"greek\">ἀνεκδιήγητα</span> <span class=\"greek\">κρίματα</span> os julgamentos indescritíveis do mundo inferior 1 Cl 20:5 (sobre o texto, ver <span class=\"greek\">ἀνεκδιήγητος</span>).—DELG s.v. <span class=\"greek\">ἔνερθε</span>(<span class=\"greek\">ν</span>).</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0243-19\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Νέρων, ωνος, ὁ</h1><div class=\"entry-meta\"><span>nome próprio masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">Νέρων</span>, <span class=\"greek\">ωνος</span>, <span class=\"greek\">ὁ</span>, Nero, imperador romano (54–68 a.d.), subscrição de 2 Ti (Mel., HE 4, 26, 9).—Kl. Pauly IV 71–73.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0243-20\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Νευης</h1><div class=\"entry-meta\"><span>nome próprio masculino; variante textual</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">Νευης</span>, forma do nome próprio do homem rico de <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.16.19\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 16:19</a>, somente em P75; ver <span class=\"greek\">Νινευής</span>.</p></section></article>\n"};
